INSERT INTO character_participations (id, character_id, campaign_id, status, class_id, class_name, subclass_name, level, xp, ability_scores, current_hp, max_hp, temp_hp, hit_dice, ac_override, speed_override, death_saves, conditions, inventory, weapons, currency, custom_resources, spells_known_prepared, spell_slots, features, notes, dm_notes, pending_level_up, joined_at, updated_at) VALUES ('part-saman-c1', 'char-saman', 'zorvania-c1', 'active', 'class-devanzad', 'دیوانزاد (Saman)', NULL, 1, 0, '{"str":15,"dex":10,"con":16,"int":14,"wis":12,"cha":8}', 12, 12, 0, '{"current":1,"max":1,"die":"d10"}', NULL, NULL, '{"successes":0,"failures":0}', '[]', '[{"id":"inv-sam-1","name":"ابزار آهنگری و اندازه‌گیری سنگ","quantity":1,"weight":3,"description":"ابزار ویژه سنجش رگه‌های برنز و سرب.","category":"misc","equipped":true,"isQuestItem":false}]', '[{"id":"w-sam-1","templateId":"wpn-sam-special","name":"چکش پژواکسنگ","damageDice":"1d6","damageType":"کوبشی (Bludgeoning)","range":"تن به تن","properties":"دو دست 1d8، سربی و برنز ورنا","kind":"special","isSpecial":true,"isShowy":false,"specialAbility":{"name":"طنین ساختار","description":"یک بار در هر استراحت کوتاه؛ مزیت در چک‌های کشف درهای مخفی و تله‌ها.","usesPerRest":1,"restType":"short"},"abilityName":"طنین ساختار","abilityDesc":"کشف ساختار پشت سنگ تا شعاع ۳۰ فوت","abilityMaxUses":1,"abilityUsed":0,"abilityReset":"short"}]', '{"gold":12,"silver":15,"copper":30}', '[]', 'null', 'null', '[{"id":"f-sam-1","name":"خون سنگ","description":"پیوند بدنی با استقامت سازه‌های دیوان و مقاومت در برابر تکانه‌ها.","source":"دیوانزاد - سطح ۱","usageType":"none","usedCount":0}]', 'بررسی قفل‌های سنگی رصدخانه با چکش پژواکسنگ انجام گیرد.', 'سامان با لمس هسته رصدخانه جرقه اول را ایجاد خواهد کرد.', 'null', 1790931285063, 1793091185063);
INSERT INTO character_participations (id, character_id, campaign_id, status, class_id, class_name, subclass_name, level, xp, ability_scores, current_hp, max_hp, temp_hp, hit_dice, ac_override, speed_override, death_saves, conditions, inventory, weapons, currency, custom_resources, spells_known_prepared, spell_slots, features, notes, dm_notes, pending_level_up, joined_at, updated_at) VALUES ('part-saman-test', 'char-saman', 'campaign-srd-test', 'active', NULL, 'Fighter (جنگجو)', NULL, 2, 300, '{"str":16,"dex":12,"con":16,"int":10,"wis":12,"cha":8}', 22, 22, 0, '{"current":2,"max":2,"die":"d10"}', NULL, NULL, '{"successes":0,"failures":0}', '[]', '[{"id":"inv-sam-test-1","name":"شمشیر بزرگ استاندارد","quantity":1,"weight":6,"description":"شمشیر فولادی دو دست","category":"weapon","equipped":true}]', '[]', '{"gold":50,"silver":0,"copper":0}', '[]', 'null', 'null', '[]', 'کمپین آزمایشی ۵e با سیستم استانداردهای سیاه‌چال.', '', 'null', 1792227285063, 1793091185063);
INSERT INTO character_participations (id, character_id, campaign_id, status, class_id, class_name, subclass_name, level, xp, ability_scores, current_hp, max_hp, temp_hp, hit_dice, ac_override, speed_override, death_saves, conditions, inventory, weapons, currency, custom_resources, spells_known_prepared, spell_slots, features, notes, dm_notes, pending_level_up, joined_at, updated_at) VALUES ('part-pardis-c1', 'char-pardis', 'zorvania-c1', 'active', 'class-farrehdar', 'فرهدار (Pardis)', NULL, 1, 0, '{"str":14,"dex":12,"con":14,"int":10,"wis":16,"cha":12}', 11, 11, 0, '{"current":1,"max":1,"die":"d8"}', NULL, NULL, '{"successes":0,"failures":0}', '[]', '[{"id":"inv-par-1","name":"زره زنجیری محافظ","quantity":1,"weight":12,"description":"زره حلقه‌ای با نشان باستانی پیمان.","category":"armor","equipped":true}]', '[{"id":"w-par-1","templateId":"wpn-par-special","name":"گرز پیمان","damageDice":"1d6","damageType":"کوبشی (Bludgeoning)","range":"تن به تن","properties":"یک دست، سر سنگی تیره","kind":"special","isSpecial":true,"isShowy":false,"specialAbility":{"name":"سپر عهد","description":"یک بار در هر استراحت کوتاه؛ واکنش (Reaction) هنگامی که هم‌پیمانی در ۵ فوتی هدف حمله قرار می‌گیرد: +۲ به درجه زرهی (AC) او در برابر آن حمله می‌دهد.","usesPerRest":1,"restType":"short"},"abilityName":"سپر عهد","abilityDesc":"+۲ به زره یار در فاصله ۵ فوتی در برابر یک حمله","abilityMaxUses":1,"abilityUsed":0,"abilityReset":"short"}]', '{"gold":15,"silver":10,"copper":20}', '[]', 'null', 'null', '[{"id":"f-par-1","name":"نشان فره","description":"نشان بیدارشده‌ای که می‌تواند سپری از نور جامد در اطراف خود و یاران ایجاد کند.","source":"فرهدار - سطح ۱","usageType":"short","maxUses":1,"usedCount":0}]', 'پردیس با نشان فره می‌تواند AC گرگ زمان‌گسسته را مهار کند.', 'پردیس در مواجهه با شهباز واکنش نشان خواهد داشت.', 'null', 1791017685063, 1793091185063);
INSERT INTO character_participations (id, character_id, campaign_id, status, class_id, class_name, subclass_name, level, xp, ability_scores, current_hp, max_hp, temp_hp, hit_dice, ac_override, speed_override, death_saves, conditions, inventory, weapons, currency, custom_resources, spells_known_prepared, spell_slots, features, notes, dm_notes, pending_level_up, joined_at, updated_at) VALUES ('part-shideh-c1', 'char-shideh', 'zorvania-c1', 'active', 'class-sayehkhan', 'سایهخوان (Shideh)', NULL, 1, 0, '{"str":10,"dex":16,"con":12,"int":14,"wis":13,"cha":10}', 9, 9, 0, '{"current":1,"max":1,"die":"d8"}', NULL, NULL, '{"successes":0,"failures":0}', '[]', '[{"id":"inv-shi-1","name":"ابزار قفل‌گشایی و جیب‌بری","quantity":1,"weight":0.5,"description":"مجموعه میله‌های برنزی نازک.","category":"misc","equipped":true}]', '[{"id":"w-shi-1","templateId":"wpn-shi-special","name":"خنجر لغزنده","damageDice":"1d4","damageType":"نافذ (Piercing)","range":"تن به تن / پرتابی (۲۰/۶۰ فوت)","properties":"چابک (Finesse)، سبک، پرتابی","kind":"special","isSpecial":true,"isShowy":false,"specialAbility":{"name":"دوختن سایه","description":"کاهش ۱۰ فوتی سرعت هدف تا پایان دور بعدی.","usesPerRest":1,"restType":"short"},"abilityName":"دوختن سایه","abilityDesc":"کاهش ۱۰ فوتی سرعت هدف تا پایان دور بعدی","abilityMaxUses":1,"abilityUsed":0,"abilityReset":"short"}]', '{"gold":18,"silver":12,"copper":10}', '[]', 'null', 'null', '[{"id":"f-shi-1","name":"پژواک لحظه","description":"مشاهده پژواک‌های روح‌مانند از گذشته یک مکان.","source":"سایهخوان - سطح ۱","usageType":"short","maxUses":1,"usedCount":0}]', 'مخفی‌کاری در سایه راهرو.', '', 'null', 1791190485063, 1793091185063);
