INSERT INTO content_packs (id, owner_id, name, description, version, visibility, kind, tags, is_default_library, created_at, updated_at) VALUES ('pack-zorvania', 'user-dm', 'زروانیا', 'بسته‌ی محتوای اسطوره‌ای جهان زروانیا: شامل ۶ کلاس سفارشی، سلاح‌های باستانی، آیتم‌های عهد و مهر، هیولاها، مکان‌های ورنا و تقویم ۳۶۵ روزه.', '1.0.0', 'instance', 'pack', '["زروانیا","فانتزی کهن","اساطیر"]', 0, 1790499285062, 1793004885062);
INSERT INTO content_packs (id, owner_id, name, description, version, visibility, kind, tags, is_default_library, created_at, updated_at) VALUES ('pack-srd-5e', 'user-dm', 'پایه ۵e', 'ساختار استاندارد و خالص قوانین ویرایش پنجم D&D (خالی از هرگونه محتوای توصیفی خارج از SRD): ۶ ویژگی اصلی، ۱۸ مهارت، تاس‌های نجات، شرایط و وضعیت‌ها، انواع آسیب، جدول ضریب مهارت و آستانه سطوح.', '1.0.0', 'instance', 'pack', '["5e","SRD","پایه"]', 0, 1790499285062, 1793004885062);
INSERT INTO content_packs (id, owner_id, name, description, version, visibility, kind, tags, is_default_library, created_at, updated_at) VALUES ('pack-desert-template', 'user-dm', 'قالب ماجراجویی کویر خاموش', 'قالب آماده کمپین ماجراجویی در بیابان و دخمه‌های کهن با تنظیمات بقا، قوانین خستگی، چند مکان کویری، هیولاهای سرگردان و سند جلسه صفر.', '1.0.0', 'instance', 'campaign_template', '["کویر","بقا","قالب","دخمه"]', 0, 1791795285062, 1793004885062);
INSERT INTO items (id, scope_type, scope_id, source_id, source_mode, created_by, name, category, is_revealed, data, updated_at) VALUES ('item-aryaman-seal', 'pack', 'item-aryaman-seal', NULL, 'copy', NULL, 'مهر آریامن', 'artifact', 1, '{"id":"item-aryaman-seal","name":"مهر آریامن","category":"artifact","rarity":"باستانی و ممنوعه","description":"دارای دو نیمه؛ هر نیمه تنها برخی مسیرها را می‌گشاید؛ مهر کامل کلید تمام دروازه‌های منشوری است.","mechanicalEffect":"باز کردن دروازه‌های منشوری و مسیرهای پلمپ‌شده معبد آریامن.","secretNotes":"در صورت به دست آوردن هر دو نیمه، دسترسی به تمام اتاق‌های هسته ممکن می‌شود.","whoItsFor":"سامان یا پردیس","isRevealed":true,"resetType":"none","updatedAt":"2026-10-27T08:54:45.062Z"}', 0);
