INSERT INTO weapon_templates (id, scope_type, scope_id, source_id, source_mode, created_by, name, kind, data, updated_at) VALUES ('wpn-sam-special', 'pack', 'wpn-sam-special', NULL, 'copy', NULL, 'چکش پژواکسنگ', 'special', '{"id":"wpn-sam-special","name":"چکش پژواکسنگ","damageDice":"1d6","damageType":"کوبشی (Bludgeoning)","range":"تن به تن","properties":"دو دست 1d8، سربی و برنز ورنا","kind":"special","specialAbility":{"name":"طنین ساختار","description":"یک بار در هر استراحت کوتاه؛ با کوبیدن دسته چکش بر زمین یا دیوار، ساختار پشت سنگ را تا شعاع ۳۰ فوت حس می‌کند؛ مزیت (Advantage) در چک‌های کشف درهای مخفی و تله‌ها.","usesPerRest":1,"restType":"short"},"description":"ساخته شده از ترکیب سرب و برنز ورنا با وزن متعادل.","secretNotes":"آثار ارتعاشی آن با سازه‌های خوابیده دیوان هماهنگ است."}', 1793091285063);
INSERT INTO weapon_templates (id, scope_type, scope_id, source_id, source_mode, created_by, name, kind, data, updated_at) VALUES ('wpn-sam-showy', 'pack', 'wpn-sam-showy', NULL, 'copy', NULL, 'تبر بزرگ کوهشکاف', 'showy', '{"id":"wpn-sam-showy","name":"تبر بزرگ کوهشکاف","damageDice":"1d12","damageType":"برشی (Slashing)","range":"تن به تن","properties":"دو دست، سنگین","kind":"showy","description":"رگه‌های کهربایی روی تیغه هنگام اصابت ضربه با صدای رعد کوتاهی می‌درخشند.","secretNotes":"جلوه بصری بالا، بدون اثر مکانیکی ویژه اضافه."}', 1793091285063);
INSERT INTO weapon_templates (id, scope_type, scope_id, source_id, source_mode, created_by, name, kind, data, updated_at) VALUES ('wpn-par-special', 'pack', 'wpn-par-special', NULL, 'copy', NULL, 'گرز پیمان', 'special', '{"id":"wpn-par-special","name":"گرز پیمان","damageDice":"1d6","damageType":"کوبشی (Bludgeoning)","range":"تن به تن","properties":"یک دست، سر سنگی تیره","kind":"special","specialAbility":{"name":"سپر عهد","description":"یک بار در هر استراحت کوتاه؛ واکنش (Reaction) هنگامی که هم‌پیمانی در ۵ فوتی هدف حمله قرار می‌گیرد: +۲ به درجه زرهی (AC) او در برابر آن حمله می‌دهد.","usesPerRest":1,"restType":"short"},"description":"سر سنگی تیره با نشانی محو و تراشیده از عهد باستان.","secretNotes":"در نزدیکی فره‌داران نور ضعیفی بازتاب می‌دهد."}', 1793091285063);
INSERT INTO weapon_templates (id, scope_type, scope_id, source_id, source_mode, created_by, name, kind, data, updated_at) VALUES ('wpn-par-showy', 'pack', 'wpn-par-showy', NULL, 'copy', NULL, 'گرز بزرگ فرهسوز', 'showy', '{"id":"wpn-par-showy","name":"گرز بزرگ فرهسوز","damageDice":"1d8","damageType":"کوبشی (Bludgeoning)","range":"تن به تن","properties":"دو دست 1d10، رگه‌های زرین","kind":"showy","description":"رگه‌های زرین و جرقه‌های کهربایی هنگام چرخش در هوا پراکنده می‌شود.","secretNotes":"فاقد قابلیت مکانیکی خاص، تاس صدمه بالاتر."}', 1793091285063);
INSERT INTO weapon_templates (id, scope_type, scope_id, source_id, source_mode, created_by, name, kind, data, updated_at) VALUES ('wpn-shi-special', 'pack', 'wpn-shi-special', NULL, 'copy', NULL, 'خنجر لغزنده', 'special', '{"id":"wpn-shi-special","name":"خنجر لغزنده","damageDice":"1d4","damageType":"نافذ (Piercing)","range":"تن به تن / پرتابی (۲۰/۶۰ فوت)","properties":"چابک (Finesse)، سبک، پرتابی","kind":"special","specialAbility":{"name":"دوختن سایه","description":"یک بار در هر استراحت کوتاه؛ پس از اصابت ضربه، سایه هدف بر زمین دوخته می‌شود و سرعت حرکت آن تا پایان دور بعدی شیده ۱۰ فوت کاهش می‌یابد.","usesPerRest":1,"restType":"short"},"description":"تیغه‌ای سیاه و صیقلی که نور را بازتاب نمی‌دهد.","secretNotes":"سایه هدف برای لحظاتی جدا از بدنش حس می‌شود."}', 1793091285063);
INSERT INTO weapon_templates (id, scope_type, scope_id, source_id, source_mode, created_by, name, kind, data, updated_at) VALUES ('wpn-shi-showy', 'pack', 'wpn-shi-showy', NULL, 'copy', NULL, 'شمشیر باریک شکافزمان', 'showy', '{"id":"wpn-shi-showy","name":"شمشیر باریک شکافزمان","damageDice":"1d6","damageType":"نافذ (Piercing)","range":"تن به تن","properties":"چابک (Finesse)","kind":"showy","description":"تیغه در هنگام برش ردی نیمه‌شفاف و لرزان در هوا بر جای می‌گذارد.","secretNotes":"فقط اثر بصری نوری دارد."}', 1793091285063);
INSERT INTO weapon_templates (id, scope_type, scope_id, source_id, source_mode, created_by, name, kind, data, updated_at) VALUES ('wpn-man-special', 'pack', 'wpn-man-special', NULL, 'copy', NULL, 'کمان ریشهبافت', 'special', '{"id":"wpn-man-special","name":"کمان ریشهبافت","damageDice":"1d4","damageType":"نافذ (Piercing)","range":"۸۰/۳۲۰ فوت","properties":"دو دست، دوربرد","kind":"special","specialAbility":{"name":"تیر نهال","description":"یک بار در هر استراحت کوتاه؛ از تیر شلیک‌شده ریشه‌های نازکی جوانه می‌زند. هدف باید در تست نجات قدرت (STR Save DC 12) موفق شود یا سرعتش تا پایان دور بعدی نصف گردد.","usesPerRest":1,"restType":"short"},"description":"کمانی بافته‌شده از ریشه‌های زنده‌ی جنگل‌های ورنا.","secretNotes":"در مجاورت خاک مرطوب بوی شکوفه می‌دهد."}', 1793091285063);
INSERT INTO weapon_templates (id, scope_type, scope_id, source_id, source_mode, created_by, name, kind, data, updated_at) VALUES ('wpn-man-showy', 'pack', 'wpn-man-showy', NULL, 'copy', NULL, 'کمان بلند ورنا', 'showy', '{"id":"wpn-man-showy","name":"کمان بلند ورنا","damageDice":"1d6","damageType":"نافذ (Piercing)","range":"۱۵۰/۶۰۰ فوت","properties":"دو دست، دوربرد","kind":"showy","description":"صدای زمزمه برگ‌ها از زه کمان شنیده می‌شود و هنگام شلیک گلبرگ‌ها از پیکان فرو می‌ریزند.","secretNotes":"برد بلندتر و تاس صدمه بالاتر بدون ویژگی مکانیکی فعال."}', 1793091285063);
INSERT INTO weapon_templates (id, scope_type, scope_id, source_id, source_mode, created_by, name, kind, data, updated_at) VALUES ('wpn-ham-special', 'pack', 'wpn-ham-special', NULL, 'copy', NULL, 'عصای آذرین', 'special', '{"id":"wpn-ham-special","name":"عصای آذرین","damageDice":"1d4","damageType":"آتشین (Fire)","range":"تن به تن","properties":"دو دست 1d8","kind":"special","specialAbility":{"name":"شعلهی پیوسته","description":"یک بار در هر استراحت کوتاه؛ به هر بازیکن در فاصله ۵ فوتی خود 1d6 جان (HP) می‌بخشد.","usesPerRest":1,"restType":"short"},"description":"چوب سوخته و سخت که سری از فلز زغال‌مانند گداخته دارد.","secretNotes":"گرمای آن به بدن یاران آرامش می‌بخشد."}', 1793091285063);
INSERT INTO weapon_templates (id, scope_type, scope_id, source_id, source_mode, created_by, name, kind, data, updated_at) VALUES ('wpn-ham-showy', 'pack', 'wpn-ham-showy', NULL, 'copy', NULL, 'گرز آتشدان', 'showy', '{"id":"wpn-ham-showy","name":"گرز آتشدان","damageDice":"1d6","damageType":"آتشین (Fire)","range":"تن به تن","properties":"یک دست","kind":"showy","description":"جرقه‌ها و خاکستر گرم با هر تاب دادن گرز در هوا معلق می‌مانند.","secretNotes":"اثر بصری آتشین بدون ترمیم جان یاران."}', 1793091285063);
INSERT INTO class_templates (id, scope_type, scope_id, source_id, source_mode, created_by, name, data, updated_at) VALUES ('class-farrehdar', 'pack', 'class-farrehdar', NULL, 'copy', NULL, 'فرهدار', '{"id":"class-farrehdar","name":"فرهدار","title":"مظهر اراده و پایداری شاهنشاهی","description":"نشان در سطح ۱ مقاومت در برابر ترس را بالا میبرد و در تاریکی اعماق زمین و سیاهچالهای دیوان منبع نور است. به جای تحلیل ذهنی از کاریزمای بالایش برای هدایت یا ارعاب استفاده میکند. با پیشرفت، بدن او ویژگیهای «زره زندار» را میپذیرد.","hitDie":"d10","saves":["WIS","CHA"],"savingThrowProficiencies":["wis","cha"],"skillChoices":{"count":2,"options":["Athletics","Insight","Intimidation","Persuasion","Religion"]},"weaponProf":"همه سلاحهای ساده و رزمی","armorProf":"همه زرهها + سپر","startingEquipment":"گرز، زره سنگین یا زره سبک + سپر، نشان فره","acFormula":"16 (زره سنگین) + 2 (سپر) = 18، مستقل از DEX","spellcasting":null,"extraAttackLevel":5,"asiLevels":[4,8,12,16,19],"fixedHpByLevel":[12,20,28,36,44,52,60,68,76,84,92,100,108,116,124,132,140,148,156,164],"hpFormula":"جدول جان ثابت (کتاب زروانیا) - فرهدار","baseAbilities":{"STR":16,"DEX":10,"CON":15,"WIS":12,"INT":8,"CHA":14},"baseAbilityScores":{"str":16,"dex":10,"con":15,"int":8,"wis":12,"cha":14},"resources":[{"name":"Divine Smite","uses":"1 بار در هر استراحت کوتاه، از سطح ۲","diceByLevel":{"2":"2d8","3":"2d8","4":"3d8","5":"3d8","6":"3d8","7":"4d8","8":"4d8","9":"4d8","10":"4d8","11":"5d8","12":"5d8","13":"5d8","14":"5d8","15":"6d8","16":"6d8","17":"6d8","18":"6d8","19":"6d8","20":"6d8"}}],"classResources":[{"id":"res-class-farrehdar-0","name":"Divine Smite","description":"1 بار در هر استراحت کوتاه، از سطح ۲","resetType":"short","maxUsesFormula":"1 بار در هر استراحت کوتاه، از سطح ۲","diceByLevel":{"2":"2d8","3":"2d8","4":"3d8","5":"3d8","6":"3d8","7":"4d8","8":"4d8","9":"4d8","10":"4d8","11":"5d8","12":"5d8","13":"5d8","14":"5d8","15":"6d8","16":"6d8","17":"6d8","18":"6d8","19":"6d8","20":"6d8"}}],"subclasses":[{"id":"sub-class-farrehdar-0","name":"سوگند نگهبان","description":"فداکاری و دریافت آسیب متحدان","unlockLevel":3,"featuresByLevel":{}},{"id":"sub-class-farrehdar-1","name":"سوگند شکارچی تاریکی","description":"نابودی موجودات مسخشدهی مهستان و سپیدارون","unlockLevel":3,"featuresByLevel":{}}],"notes":"نشان در سطح ۱ مقاومت در برابر ترس را بالا میبرد و در تاریکی اعماق زمین و سیاهچالهای دیوان منبع نور است. به جای تحلیل ذهنی از کاریزمای بالایش برای هدایت یا ارعاب استفاده میکند. با پیشرفت، بدن او ویژگیهای «زره زندار» را میپذیرد.","features":{"1":"نشان فره","2":"ضربه فره (فعال)","3":"سوگند آریامن","4":"زره زندار + ASI","5":"Extra Attack + ندای نگهبان","6":"وارث عهد آریامن","7":"فیچر سوگند (سطح ۲)","8":"ASI","9":"مقاومت آسیب عنصری","10":"اورای الهامبخش","11":"ضربه فره بهبودیافته","12":"ASI","13":"فیچر سوگند (سطح ۳)","14":"مقاومت ترس متحدان","15":"زره زندار بهبودیافته","16":"ASI","17":"فیچر سوگند (سطح ۴)","18":"اورا ۹ متر","19":"ASI","20":"آواتار آریامن (Capstone)"},"featuresByLevel":{"1":[{"name":"نشان فره","description":"","usage":"none"}],"2":[{"name":"ضربه فره (فعال)","description":"","usage":"none"}],"3":[{"name":"سوگند آریامن","description":"","usage":"none"}],"4":[{"name":"زره زندار + ASI","description":"","usage":"none"}],"5":[{"name":"Extra Attack + ندای نگهبان","description":"","usage":"none"}],"6":[{"name":"وارث عهد آریامن","description":"","usage":"none"}],"7":[{"name":"فیچر سوگند (سطح ۲)","description":"","usage":"none"}],"8":[{"name":"ASI","description":"","usage":"none"}],"9":[{"name":"مقاومت آسیب عنصری","description":"","usage":"none"}],"10":[{"name":"اورای الهامبخش","description":"","usage":"none"}],"11":[{"name":"ضربه فره بهبودیافته","description":"","usage":"none"}],"12":[{"name":"ASI","description":"","usage":"none"}],"13":[{"name":"فیچر سوگند (سطح ۳)","description":"","usage":"none"}],"14":[{"name":"مقاومت ترس متحدان","description":"","usage":"none"}],"15":[{"name":"زره زندار بهبودیافته","description":"","usage":"none"}],"16":[{"name":"ASI","description":"","usage":"none"}],"17":[{"name":"فیچر سوگند (سطح ۴)","description":"","usage":"none"}],"18":[{"name":"اورا ۹ متر","description":"","usage":"none"}],"19":[{"name":"ASI","description":"","usage":"none"}],"20":[{"name":"آواتار آریامن (Capstone)","description":"","usage":"none"}]},"startingFeatures":[{"id":"feat-class-farrehdar-1","name":"نشان فره","description":"نشان در سطح ۱ مقاومت در برابر ترس را بالا میبرد و در تاریکی اعماق زمین و سیاهچالهای دیوان منبع نور است. به جای تحلیل ذهنی از کاریزمای بالایش برای هدایت یا ارعاب استفاده میکند. با پ","source":"فرهدار - سطح ۱","usageType":"short","maxUses":1}],"level2Options":["ضربه فره (فعال)"],"starterWeaponOptions":["wpn-par-special","wpn-par-showy"],"updatedAt":"2026-10-27T08:54:45.060Z"}', 0);
INSERT INTO class_templates (id, scope_type, scope_id, source_id, source_mode, created_by, name, data, updated_at) VALUES ('class-azarin', 'pack', 'class-azarin', NULL, 'copy', NULL, 'موبد آذرین', '{"id":"class-azarin","name":"موبد آذرین","title":"حافظ شعلهی خاطرات","description":"«شعله حافظه» در سطح ۱ ردپای اتفاقات گذشته را در اشیا و مکانها نشان میدهد. مسیر او از درمان زخمهای ساده در سطح ۲ به پاکسازی نفرینها و افشای توهمات در سطوح بالا میرود.","hitDie":"d8","saves":["WIS","INT"],"savingThrowProficiencies":["wis","int"],"skillChoices":{"count":2,"options":["History","Insight","Medicine","Religion"]},"weaponProf":"سلاحهای ساده + چوبدستی","armorProf":"هیچ زره یا سپری","startingEquipment":"چوبدستی، کیف دارویی، لباس ساده","acFormula":"10 + DEX mod + WIS mod (Unarmored Defense؛ با پوشیدن هر زره یا سپر غیرفعال میشود)","spellcasting":{"ability":"WIS","dc":"8 + Proficiency + WIS mod","slots":"FULL_CASTER_SLOTS","spells":{"1":["آتش پاککننده (Cure Wounds)","بازتاب کوچک (Shield of Faith)","آشکارسازی نیت (Detect Evil and Good)"],"2":["شعله داوری (Zone of Truth)","درمان مصدومیت (Lesser Restoration)","سکوت (Silence)"],"3":["آتش زندگی (Mass Healing Word)","رفع نفرین (Remove Curse)","بازگشت روح موقت (Speak with Dead)"],"4":["خاطره شعلهور (Divination)","محافظ آتشین (Guardian of Faith)"],"5":["شعله جاودان (Raise Dead)","دفع فساد (Dispel Evil and Good)"],"cantrips":["شراره فره (Sacred Flame: 1d8 radiant, Save DEX)","لمس درمان (Spare the Dying)"]},"slotsByLevel":{"1":[2],"2":[3],"3":[4,2],"4":[4,3],"5":[4,3,2],"6":[4,3,3],"7":[4,3,3,1],"8":[4,3,3,2],"9":[4,3,3,3,1],"10":[4,3,3,3,2],"11":[4,3,3,3,2,1],"12":[4,3,3,3,2,1],"13":[4,3,3,3,2,1,1],"14":[4,3,3,3,2,1,1],"15":[4,3,3,3,2,1,1,1],"16":[4,3,3,3,2,1,1,1],"17":[4,3,3,3,2,1,1,1,1],"18":[4,3,3,3,3,1,1,1,1],"19":[4,3,3,3,3,2,1,1,1],"20":[4,3,3,3,3,2,2,1,1]},"saveDCFormula":"8 + Proficiency + WIS mod"},"extraAttackLevel":null,"asiLevels":[4,8,12,16,19],"fixedHpByLevel":[9,15,21,27,33,39,45,51,57,63,69,75,81,87,93,99,105,111,117,123],"hpFor