INSERT INTO class_templates (id, scope_type, scope_id, source_id, source_mode, created_by, name, data, updated_at) VALUES ('class-peymanban', 'pack', 'class-peymanban', NULL, 'copy', NULL, 'پیمانبان', '{"id":"class-peymanban","name":"پیمانبان","title":"فرزند خاموش طبیعت (پیمانبان ورنا)","description":"«زبان ریشهها» پیوندی با موجودات زنده میسازد. «گام ورنا» (سطح ۲) حرکت بیصدا در طبیعت است. «تغییر ورنایی» (سطح ۳) به او اجازه میدهد ویژگیهای حیوانات را برای مدت کوتاه به امانت بگیرد.","hitDie":"d10","saves":["STR","WIS"],"savingThrowProficiencies":["str","wis"],"skillChoices":{"count":3,"options":["Animal Handling","Nature","Perception","Survival","Stealth"]},"weaponProf":"سلاحهای ساده + کمانهای ساده و رزمی","armorProf":"زره سبک و متوسط، سپر","startingEquipment":"کمان کوتاه، زره چرمی، کیسه بذر ورنا","acFormula":"11 (چرم) + DEX mod  یا  13 (متوسط) + min(DEX, +2)","spellcasting":{"ability":"WIS","dc":"8 + Proficiency + WIS mod","slots":"HALF_CASTER_SLOTS","spells":{"1":["زبان ریشهها (Speak with Animals)","پیوند شکارچی (Hunter''s Mark)","درمان طبیعی (Cure Wounds)"],"2":["گام ورنا (Pass without Trace)","تغییر ورنایی مقدماتی (Beast Sense)","دام گیاهی (Entangle)"],"3":["تغییر ورنایی (Conjure Animals بازطراحیشده)","سرعت گراز (Haste)"],"4":["همراه جنگل تقویتشده (Conjure Woodland Beings)","مصونیت به عناصر (Protection from Energy)"],"5":["خشم ورنا (Insect Plague / Sleet Storm)","تجدید حیات جنگل (Reincarnate)"],"cantrips":["پیام گیاه (Druidcraft)","رشد ناگهانی (Thorn Whip)"]},"slotsByLevel":{"1":[],"2":[2],"3":[3],"4":[3],"5":[4,2],"6":[4,2],"7":[4,3],"8":[4,3],"9":[4,3],"10":[4,3],"11":[4,3],"12":[4,3],"13":[4,3],"14":[4,3],"15":[4,3],"16":[4,3],"17":[4,4],"18":[4,4],"19":[4,4],"20":[4,4]},"saveDCFormula":"8 + Proficiency + WIS mod"},"extraAttackLevel":5,"asiLevels":[4,8,12,16,19],"fixedHpByLevel":[11,18,25,32,39,46,53,60,67,74,81,88,95,102,109,116,123,130,137,144],"hpFormula":"جدول جان ثابت (کتاب زروانیا) - پیمانبان","baseAbilities":{"STR":10,"DEX":16,"CON":12,"WIS":16,"INT":10,"