INSERT INTO class_templates (id, scope_type, scope_id, source_id, source_mode, created_by, name, data, updated_at) VALUES ('class-meh-ashna', 'pack', 'class-meh-ashna', NULL, 'copy', NULL, 'مهآشنا', '{"id":"class-meh-ashna","name":"مهآشنا","title":"سرگردان میان لحظهها","description":"«لرزش ادراک» خود یا اشیای کوچک را نیمشفاف میکند. «پژواک گمشده» رد افراد گمشده در شکافهای زمانی را حس میکند.","hitDie":"d8","saves":["STR","DEX"],"savingThrowProficiencies":["str","dex"],"skillChoices":{"count":2,"options":["Acrobatics","History","Insight","Religion","Stealth"]},"weaponProf":"سلاحهای ساده + شمشیر کوتاه","armorProf":"هیچ زره یا سپری","startingEquipment":"۱۰ عدد Dart، لباس راهبانه","acFormula":"10 + DEX mod + WIS mod (Unarmored Defense؛ با پوشیدن هر زره یا سپر غیرفعال میشود)","spellcasting":null,"extraAttackLevel":5,"asiLevels":[4,8,12,16,19],"fixedHpByLevel":[9,15,21,27,33,39,45,51,57,63,69,75,81,87,93,99,105,111,117,123],"hpFormula":"جدول جان ثابت (کتاب زروانیا) - مهآشنا","baseAbilities":{"STR":8,"DEX":15,"CON":12,"WIS":16,"INT":13,"CHA":10},"baseAbilityScores":{"str":8,"dex":15,"con":12,"int":13,"wis":16,"cha":10},"resources":[{"name":"امتیاز لحظه","uses":"= سطح کاراکتر"}],"classResources":[{"id":"res-class-meh-ashna-0","name":"امتیاز لحظه","description":"= سطح کاراکتر","resetType":"long","maxUsesFormula":"= سطح کاراکتر"}],"subclasses":[{"id":"sub-class-meh-ashna-0","name":"راه لحظهی سرگردان","description":"تردیشن؛ فیچرها در سطوح ۳، ۶، ۱۱ و ۱۷","unlockLevel":3,"featuresByLevel":{}}],"notes":"«لرزش ادراک» خود یا اشیای کوچک را نیمشفاف میکند. «پژواک گمشده» رد افراد گمشده در شکافهای زمانی را حس میکند.","features":{"1":"لرزش ادراک","2":"پژواک گمشده","3":"(تردیشن) قدم بیرون از لحظه","4":"ASI","5":"Extra Attack","6":"(تردیشن) صدای دوپاره","7":"حرکت بیصدا در زمان","8":"ASI","9":"رهایی از وضعیت","10":"مصونیت به سم","11":"(تردیشن) لنگر خاطره","12":"ASI","13":"حرکت میان لحظهها","14":"مصونیت سیوهای WIS/CHA","15":"بازگشت از مرز مرگ","16":"ASI","17":"(تردیشن) ایستاده میان دو لحظه","1