INSERT INTO rewards (id, scope_type, scope_id, source_id, source_mode, created_by, title, data, created_at) VALUES ('rew-session-2', 'campaign', 'zorvania-c1', NULL, 'copy', NULL, 'پاداش حل معمای رصدخانه ریشه‌ها', '{"id":"rew-session-2","title":"پاداش حل معمای رصدخانه ریشه‌ها","description":"غنیمت اکتشاف تالار ساعت و نجات پری مه‌آشنا.","gold":25,"silver":30,"skillPoints":1,"items":[{"id":"rew-item-1","name":"شهد بهار کهن","quantity":1,"weight":0.5,"description":"کوزه کوچک حاوی مایع ترمیم‌بخش باستانی.","category":"consumable","equipped":false,"isQuestItem":false,"isNewBadge":true}],"createdAt":"2026-10-27T08:54:45.062Z"}', 0);
INSERT INTO campaign_notes (id, scope_type, scope_id, title, category, session_number, data, updated_at) VALUES ('cn-session-1', 'campaign', 'zorvania-c1', 'خلاصه جلسه ۱: درخشش سنگ خاموش', 'session', 'جلسه ۱', '{"id":"cn-session-1","title":"خلاصه جلسه ۱: درخشش سنگ خاموش","sessionNumber":"جلسه ۱","category":"session","content":"گروه در پیرامون سازه‌های کهن گرد هم آمدند. سامان با لمس سنگ خاموش ارتعاشات دیوان را حس کرد و اولین نشانه‌های مهر آریامن آشکار گردید.","tags":["جلسه۱","درخشش_سنگ_خاموش","سامان","آریامن"],"updatedAt":"2026-10-27T08:54:45.062Z"}', 0);
INSERT INTO campaign_notes (id, scope_type, scope_id, title, category, session_number, data, updated_at) VALUES ('cn-session-2', 'campaign', 'zorvania-c1', 'خلاصه جلسه ۲: رصدخانهی ریشههای خاموش', 'session', 'جلسه ۲', '{"id":"cn-session-2","title":"خلاصه جلسه ۲: رصدخانهی ریشههای خاموش","sessionNumber":"جلسه ۲","category":"session","content":"ورود گروه به رصدخانه ریشه‌های خاموش؛ رویارویی با گسستهزمان، کشف بقایای ساعت‌های سه فاز و ارتباط مانا با نبض ریشه‌ها.","tags":["جلسه۲","رصدخانه_ریشههای_خاموش","ورنا","گسستهزمان"],"updatedAt":"2026-10-27T08:54:45.062Z"}', 0);
INSERT INTO campaign_notes (id, scope_type, scope_id, title, category, session_number, data, updated_at) VALUES ('cn-factions', 'campaign', 'zorvania-c1', 'دانشنامه گروه‌ها و جناح‌های زروانیا (Factions)', 'lore', NULL, '{"id":"cn-factions","title":"دانشنامه گروه‌ها و جناح‌های زروانیا (Factions)","category":"lore","content":"جناح‌های سه‌گانه حاضر در جهان زروانیا:\n۱. نوژان (Nozhan): جادو را با آغوش باز می‌پذیرند و به دنبال کشف و احیای جریان‌های باستانی هستند.\n۲. رهامان (Rohaman): مصمم به نابودی هرگونه جادو و پاکسازی آثار ناشی از شکست زمان.\n۳. پیمانداران (Peymandaran): خواهان کنترل، نظم و ثبات؛ در حال حاضر بیشترین نفوذ و تسلط را در ارکان حکومت در اختیار دارند.","tags":["جناح‌ها","نوژان","رهامان","پیمانداران","لور"],"updatedAt":"2026-10-27T08:54:45.062Z"}', 0);
INSERT INTO npcs (id, scope_type, scope_id, source_id, source_mode, created_by, name, type, is_revealed, location_tag, session_tag, data, updated_at) VALUES ('npc-time-fractured-wolf', 'pack', 'npc-time-fractured-wolf', NULL, 'copy', NULL, 'گسستهزمان', 'minion', 1, 'راهروهای مرزی معبد', 'جلسه ۲', '{"id":"npc-time-fractured-wolf","name":"گسستهزمان","type":"minion","portraitUrl":"https://images.unsplash.com/photo-1564865878688-9a244444042a?auto=format&fit=crop&w=400&q=80","description":"گرگ غول‌پیکر جهش‌یافته با تاروپود زمانی شکسته. حرکات نامنظم و جهش‌های تله‌پورت‌مانند غیرقابل پیش‌بینی دارد.","locationTag":"راهروهای مرزی معبد","sessionTag":"جلسه ۲","ac":"آشوبناک ۱۶ / مهارشده ۱۰ (با نشان فره پردیس)","hp":{"current":55,"max":55},"speed":"۱۲ متر (جهش‌های تله‌پورت زمانی)","abilities":{"str":15,"dex":18,"con":14,"int":4,"wis":12,"cha":2},"savingThrows":"چابکی +۶","resistances":"آسیب زمانی، سرعت متغیر","vulnerabilities":"نور جامد فره (تثبیت AC به ۱۰)","immunities":"وضعیت کندی (Slow)","attacks":[{"id":"atk-gw-1","name":"ورود اولیه","toHit":"آزمون DC 16 چابکی","damage":"حمله ناگهانی در مسیر حرکت","dc":"DC 16 Dex","notes":"برای قرار نگرفتن در مسیر هجوم اولیه باید تست چابکی با DC 16 داده شود."},{"id":"atk-gw-2","name":"حملهی فرسایش سن","toHit":"آزمون DC 13 بنیه","damage":"کاهش توان چابکی","dc":"DC 13 Con","notes":"در صورت شکست، مادیفایر چابکی (DEX Modifier) هدف نصف می‌شود."},{"id":"atk-gw-3","name":"لغزش زمانی","toHit":"آزمون DC 13 چابکی","damage":"افزایش به AC و نصف شدن صدمه وارده","dc":"DC 13 Dex","notes":"در صورت موفقیت در تست چابکی DC 13، صدمه نصف می‌شود."},{"id":"atk-gw-4","name":"چنگ انداختن","toHit":"+۵ برای اصابت","damage":"1d8 + 4 برشی","notes":"ضربه مستقیم فیزیکی با پنجه‌های تیز."}],"specialAbilities":[{"id":"sa-gw-1","name":"حرکت تله‌پورت‌گونه پیش‌بینی‌ناپذیر","description":"در انتهای هر نوبت، چند فوت در بعد زمان جابجا می‌شود و موقعیت ثابتی روی نقشه ندارد."}],"tacticsTips":"نشان فره پردیس درجه زرهی آن را از ۱۶ به ۱۰ می‌شکند. یادداشت دانجن مستر: ترتیب آمارها به عنوان STR/DEX/CON/WIS/INT/CHA ثبت شده اما به دلیل دوگانگی ستون‌های هوش و خرد، با احتیاط داوری شود.","lootDrops":"پوست متراکم زمانی، ۳۰ سکه نقره کهن","dialogueLines":["*غرش بم که پژواک آن قبل از باز شدن دهانش شنیده می‌شود*"],"isRevealed":true,"notes":"توجه DM: ترتیب ویژگی‌ها در سند اصلی با برچسب هوش (WIS) و خرد (INT) ثبت شده بود.","updatedAt":"2026-10-27T08:54:45.062Z"}', 0;
INSERT INTO npcs (id, scope_type, scope_id, source_id, source_mode, created_by, name, type, is_revealed, location_tag, session_tag, data, updated_at) VALUES ('npc-time-lost-guardian', 'pack', 'npc-time-lost-guardian', NULL, 'copy', NULL, 'نگهبان زمانگم', 'boss', 0, 'برج ساعت کهن', 'جلسه ۲', '{"id":"npc-time-lost-guardian","name":"نگهبان زمانگم","type":"boss","portraitUrl":"https://images.unsplash.com/photo-1579783902614-a3fb3927b675?auto=format&fit=crop&w=400&q=80","description":"نگهبان پری تباه‌شده از غرب ورنا که میان فازهای خردسالی، میانسالی و کهنسالی نوسان می‌کند. پس از نجات، او همان کاراکتر سیاوش (مه‌آشنا) خواهد شد.","locationTag":"برج ساعت کهن","sessionTag":"جلسه ۲","ac":"۱۴","hp":{"current":50,"max":50},"speed":"۳۰ فوت (۹ متر)","abilities":{"str":10,"dex":16,"con":12,"int":14,"wis":15,"cha":12},"savingThrows":"خرد +۴، چابکی +۵","resistances":"حملاتی که با فاز فعلی سنی او تطابق ندارند نصف صدمه می‌زنند","vulnerabilities":"ضربات منطبق بر فاز، +۱ به \"شکنندگی فاز (Phase Fragility)\" اضافه می‌کنند","immunities":"خواب جادویی","attacks":[{"id":"atk-tlg-1","name":"ضربه تماسی","toHit":"+۴ برای اصابت","damage":"1d8 + 2 کوبشی/زمانی","notes":"لمس دست لرزان که سن هدف را برای ثانیه‌ای تغییر می‌دهد."},{"id":"atk-tlg-2","name":"پژواک زمانی","toHit":"آزمون DC 12 خرد","damage":"2d6 صدمه روانی/زمانی","dc":"DC 12 Wis","notes":"در هر راند یک بازیکن 2d6 صدمه روانی/زمانی می‌خورد؛ نجات خرد DC 12 صدمه را نصف می‌کند."}],"specialAbilities":[{"id":"sa-tlg-phases","name":"قانون فازها (خردسالی / میانسالی / کهنسالی)","description":"حملاتی که با فاز فعلی مطابقت ندارند نصف صدمه می‌زنند. ضربات منطبق +۱ به \"شکنندگی فاز\" می‌افزایند؛ در عدد ۳، ساعت مربوطه به طور خودکار پایدار می‌شود."},{"id":"sa-tlg-puzzle","name":"معمای ساعت‌ها در قفس‌ها","description":"انداختن ساعت‌ها (کوچک / کهنه / شکسته) در قفس‌های متناظر با فاز سنی، نوسان را باطل می‌کند."},{"id":"sa-tlg-safefail","name":"شکست امن (Safe-fail)","description":"اگر گروه در نبرد مغلوب شود، کشته نمی‌شوند بلکه بیهوش می‌گردند. با نجات یافتن او، نگهبان بیدار شده و به پی‌سی سیاوش تبدیل می‌گردد."}],"tacticsTips":"به بازیکنان فرصت دهید رابطه بین فازهای سنی و ساعت‌ها را کشف کنند.","lootDrops":"ساعت‌های سه فاز، خاکستر زمان","dialogueLines":["من... مادرم کجاست؟ نه، من قرن‌هاست اینجا کشیک می‌کشم...","پژواک‌ها دست از سرم برنمی‌دارند!"],"isRevealed":false,"updatedAt":"2026-10-27T08:54:45.062Z"}', 0;
INSERT INTO npcs (id, scope_type, scope_id, source_id, source_mode, created_by, name, type, is_revealed, location_tag, session_tag, data, updated_at) VALUES ('npc-ancient-sleeper-guardian', 'pack', 'npc-ancient-sleeper-guardian', NULL, 'copy', NULL, 'نگهبان اصلی باغستان کهن (سنگخواب فعال‌شده)', 'boss', 0, 'هسته باغستان کهن', 'پایان بخش باغستان', '{"id":"npc-ancient-sleeper-guardian","name":"نگهبان اصلی باغستان کهن (سنگخواب فعال‌شده)","type":"boss","portraitUrl":"https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=400&q=80","description":"سازه‌ی سنگی عظیم حدود ۴ متری که برای محافظت از هسته باغستان بیدار شده است. صفحه‌های زرهی پولادین و رگه‌های برنز دارد.","locationTag":"هسته باغستان کهن","sessionTag":"پایان بخش باغستان","ac":"۱۸ (در حالت عادی) / ۱۲ (با دندان‌کلید)","hp":{"current":120,"max":120},"speed":"۲۰ فوت (۶ متر)","abilities":{"str":18,"dex":8,"con":18,"int":10,"wis":10,"cha":6},"savingThrows":"قدرت +۵، بنیه +۶","resistances":"صدمات فیزیکی (کوبشی، برشی، نافذ) نصف می‌شود","vulnerabilities":"آسیب نور/فره، آتش و صدمات جادویی/روانی مقاومت را دور می‌زنند","immunities":"سم، مسمومیت، ترس، خواب","attacks":[{"id":"atk-sg-1","name":"ضربهی محاسبهشده","toHit":"+۵ برای اصابت","damage":"2d10 + 4 برشی/کوبشی","notes":"برد ۱۰ فوت؛ ضربه ویرانگر شمشیر سنگی سنگین."},{"id":"atk-sg-2","name":"راند ۱: کوبش زمینلرزه","toHit":"آزمون DC 13 چابکی در شعاع ۱۵ فوت","damage":"2d6 کوبشی + افتادن بر زمین (Prone)","dc":"DC 13 Dex","notes":"در صورت موفقیت در تست، صدمه نصف شده و کاراکتر زمین نمی‌خورد."}],"specialAbilities":[{"id":"sa-sg-round3","name":"راند ۳: گشوده شدن صفحه‌های سینه","trigger":"شروع راند ۳ تا پایان راند ۴","description":"صفحه‌های سینه گشوده شده و \"سنگ نفس باغستان\" تا پایان راند ۴ آشکار می‌گردد."},{"id":"sa-sg-mechkill","name":"کشتن مکانیکی: دندانکلید بیدندانه","description":"استفاده از دندانکلید روی هسته (چک Sleight of Hand با DC 12، هزینه یک اکشن کامل): سازه ۱ دور گیج (Stunned) می‌شود، AC به ۱۲ افت می‌کند و مقاومت فیزیکی‌اش باطل می‌گردد."},{"id":"sa-sg-peace","name":"مسیر صلح‌آمیز و غیرکشنده (خون دیوانزاد سامان)","description":"سامان با لمس سازه خون دیوانزاد خود را به آن می‌شناساند؛ سازه اعلام می‌کند: \"ساختار خونیِ معمار شناسایی شد. کاربر با سطح دسترسی ۰ تأیید شد.\" و به نشانه تعظیم خاموش می‌شود."}],"tacticsTips":"نکات راند به راند DM: در راند ۲ تشدید ارتعاش سازه با سامان رخ می‌دهد و به او سرنخ لمس داده می‌شود.","lootDrops":"سنگ نفس باغستان (آرتیفکت)، برنز خالص ورنا، هسته مکانیکی","dialogueLines":["*صدای بم فعال‌سازی هیدرولیک سنگی*","ساختار خونیِ معمار شناسایی شد. کاربر با سطح دسترسی ۰ تأیید شد."],"isRevealed":false,"notes":"نکات محرمانه DM: راند ۲ ارتعاش متقابل با چکش و خون سامان احساس می‌شود.","updatedAt":"2026-10-27T08:54:45.062Z"}', 0;
INSERT INTO npcs (id, scope_type, scope_id, source_id, source_mode, created_by, name, type, is_revealed, location_tag, session_tag, data, updated_at) VALUES ('npc-broken-sleeper', 'pack', 'npc-broken-sleeper', NULL, 'copy', NULL, 'سنگخواب خراب (باغستان)', 'hazard', 1, 'ورودی باغستان کهن', 'جلسه ۲', '{"id":"npc-broken-sleeper","name":"سنگخواب خراب (باغستان)","type":"hazard","portraitUrl":"https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=400&q=80","description":"مجسمه سنگ‌خواب شکسته که بدون هدف شمشیر بزرگی را در هوا می‌چرخاند و پی‌درپی خطا می‌زند. آماری برای آن تعریف نشده و بیشتر نقش مانع محیطی را دارد.","locationTag":"ورودی باغستان کهن","sessionTag":"جلسه ۲","ac":"۱۰","hp":{"current":20,"max":20},"speed":"۰ (ثابت در محل)","abilities":{"str":16,"dex":6,"con":14,"int":1,"wis":1,"cha":1},"savingThrows":"ندارد","resistances":"سنگی","vulnerabilities":"ندارد","immunities":"وضعیت‌های روانی","attacks":[{"id":"atk-bs-1","name":"چرخش کورکورانه شمشیر بزرگ","toHit":"+۰","damage":"2d6 برشی (معمولاً به هوا می‌خورد)","notes":"مانع محیطی؛ بازیکنان با گذر با دقت می‌توانند از آن عبور کنند."}],"specialAbilities":[],"tacticsTips":"یک خطر محیطی ساده برای آزمایش واکنش‌های بازیکنان.","lootDrops":"فلز شکسته شمشیر کهن","dialogueLines":["*صدای غیژغیژ چرخ‌دنده‌های شکسته*"],"isRevealed":true,"updatedAt":"2026-10-27T08:54:45.062Z"}', 0;
INSERT INTO npcs (id, scope_type, scope_id, source_id, source_mode, created_by, name, type, is_revealed, location_tag, session_tag, data, updated_at) VALUES ('npc-faranaz', 'pack', 'npc-faranaz', NULL, 'copy', NULL, 'فراناز', 'ally', 1, 'اردوگاه پریان ورنا', 'جلسه ۱ و ۲', '{"id":"npc-faranaz","name":"فراناز","type":"ally","portraitUrl":"https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=400&q=80","description":"فرمانده پریان ورنا؛ سرد، دانا، هرگز مستقیماً در چشمان طرف مقابل خیره نمی‌شود و هاله‌ها را می‌خواند؛ به تدریج حقایق را دریغ می‌کند و قطره‌چکانی بروز می‌دهد.","locationTag":"اردوگاه پریان ورنا","sessionTag":"جلسه ۱ و ۲","ac":"۱۵","hp":{"current":35,"max":35},"speed":"۹ متر، پرواز ۹ متر","abilities":{"str":8,"dex":16,"con":12,"int":16,"wis":17,"cha":16},"savingThrows":"خرد +۶","resistances":"سحرآمیز","vulnerabilities":"ندارد","immunities":"خواب","attacks":[],"specialAbilities":[{"id":"sa-faranaz-aura","name":"خواندن هاله","description":"هاله روحی افراد را تحلیل کرده و نیات آنان را می‌سنجد."}],"tacticsTips":"او به عنوان متحد پشتیبان و مأموریت‌دهنده عمل می‌کند.","lootDrops":"کوزه‌های شهد بهار، نشان فرماندهی ورنا","dialogueLines":["هاله‌ی تو... نوسان دارد، مسافر.","تمام حقایق را نمی‌توان به یکباره در برابر چشمان فانی گشود."],"isRevealed":true,"updatedAt":"2026-10-27T08:54:45.062Z"}', 0;
INSERT INTO npcs (id, scope_type, scope_id, source_id, source_mode, created_by, name, type, is_revealed, location_tag, session_tag, data, updated_at) VALUES ('npc-varnoosh', 'pack', 'npc-varnoosh', NULL, 'copy', NULL, 'ورنوش', 'neutral', 1, 'حاشیه بیشه خاموش', 'جلسه ۲', '{"id":"npc-varnoosh","name":"ورنوش","type":"neutral","portraitUrl":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&q=80","description":"پری تبعیدشده با موهای خاکستری مات؛ در دل گروه نسبت به فراناز و اهدافش بذر شک و تردید می‌کارد.","locationTag":"حاشیه بیشه خاموش","sessionTag":"جلسه ۲","ac":"۱۲","hp":{"current":20,"max":20},"speed":"۹ متر","abilities":{"str":9,"dex":14,"con":11,"int":13,"wis":12,"cha":15},"savingThrows":"فرهمندی +۴","resistances":"ندارد","vulnerabilities":"ندارد","immunities":"ندارد","attacks":[],"specialAbilities":[],"tacticsTips":"پنهان‌کاری و ایجاد تردید در بازیکنان نسبت به دستورات فراناز.","lootDrops":"دست‌نوشته‌های اعتراض‌آمیز ورنا","dialogueLines":["آیا تا به حال از خود پرسیده‌اید چرا فراناز چشم در چشمان شما نمی‌دوزد؟","او همه‌چیز را به شما نمی‌گوید... مراقب بهای وعده‌هایش باشید."],"isRevealed":true,"updatedAt":"2026-10-27T08:54:45.062Z"}', 0;
INSERT INTO npcs (id, scope_type, scope_id, source_id, source_mode, created_by, name, type, is_revealed, location_tag, session_tag, data, updated_at) VALUES ('npc-samiar', 'pack', 'npc-samiar', NULL, 'copy', NULL, 'سامیار', 'merchant', 1, 'کاروانسرای کویر خاموش', 'جلسه ۲', '{"id":"npc-samiar","name":"سامیار","type":"merchant","portraitUrl":"https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=400&q=80","description":"عتیقه‌فروش و بازرگان کویر خاموش؛ عاشق غذای پریان؛ دست‌های سریع و تردستی (Sleight-of-hand).","locationTag":"کاروانسرای کویر خاموش","sessionTag":"جلسه ۲","ac":"۱۳","hp":{"current":18,"max":18},"speed":"۹ متر","abilities":{"str":10,"dex":16,"con":12,"int":14,"wis":11,"cha":15},"savingThrows":"چابکی +۵","resistances":"ندارد","vulnerabilities":"ندارد","immunities":"ندارد","attacks":[{"id":"atk-sam-1","name":"خنجر مخفی","toHit":"+۵","damage":"1d4 + 3"}],"specialAbilities":[],"tacticsTips":"در برابر غذای پریان ورنا حاضر است عتیقه‌های نایاب مبادله کند.","lootDrops":"دندانکلید بیدندانه، کیسه سکه‌های طلا","dialogueLines":["غذای پریان؟ بوی عسل وحشی ورنا را از فرسنگ‌ها حس می‌کنم! بیایید معامله کنیم...","این عتیقه بی‌دندانه شاید به کارتان بیاید، اما غذای تازه بهای آن است!"],"isRevealed":true,"updatedAt":"2026-10-27T08:54:45.062Z"}', 0;
INSERT INTO npcs (id, scope_type, scope_id, source_id, source_mode, created_by, name, type, is_revealed, location_tag, session_tag, data, updated_at) VALUES ('npc-pivar-sandar', 'pack', 'npc-pivar-sandar', NULL, 'copy', NULL, 'پیوار و سندار', 'ally', 1, 'دروازه انجمن آوند', 'جلسه ۱ و ۲', '{"id":"npc-pivar-sandar","name":"پیوار و سندار","type":"ally","portraitUrl":"https://images.unsplash.com/photo-1568602471122-7832951cc4c5?auto=format&fit=crop&w=400&q=80","description":"نگهبانان غول‌پیکر حدود ۴ متری از دیوان؛ متحدان کمدی گروه که نامرئی‌شدنشان معیوب است و بخش‌هایی از بدنشان هویدا می‌ماند؛ سندار از سفر انتقالی آوندی (Avand-travel) وحشت دارد.","locationTag":"دروازه انجمن آوند","sessionTag":"جلسه ۱ و ۲","ac":"۱۴","hp":{"current":65,"max":65},"speed":"۹ متر","abilities":{"str":19,"dex":8,"con":16,"int":8,"wis":9,"cha":10},"savingThrows":"قدرت +۶","resistances":"کوبشی","vulnerabilities":"ندارد","immunities":"ندارد","attacks":[{"id":"atk-ps-1","name":"کوبش مشت دیو","toHit":"+۶","damage":"2d8 + 4"}],"specialAbilities":[{"id":"sa-faulty-invis","name":"نامرئی‌شدن معیوب","description":"هنگام نامرئی شدن، چکمه‌ها یا شاخ‌هایشان همچنان در هوا معلق و قابل دیدن می‌ماند!"}],"tacticsTips":"محافظان پرقدرت اما ساده‌دل برای کمک به گروه در حمل بارهای سنگین.","lootDrops":"گرزهای سنگی عظیم","dialogueLines":["پیوار، کلاهم نامرئی شد؟ نه سندار، هنوز شست پایت مثل فانوس می‌درخشد!","خواهش می‌کنم از آوند استفاده نکنیم... سرگیجه‌اش تا سه روز با من است!"],"isRevealed":true,"updatedAt":"2026-10-27T08:54:45.062Z"}', 0;
INSERT INTO npcs (id, scope_type, scope_id, source_id, source_mode, created_by, name, type, is_revealed, location_tag, session_tag, data, updated_at) VALUES ('npc-pir-barzin', 'pack', 'npc-pir-barzin', NULL, 'copy', NULL, 'پیر-برزین', 'quest-giver', 1, 'تالار انجمن آوند', 'جلسه ۲', '{"id":"npc-pir-barzin","name":"پیر-برزین","type":"quest-giver","portraitUrl":"https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=400&q=80","description":"سرمعمار حدود ۴ متری دیوان و ریش‌سفید انجمن آوند؛ ردایی از کتان ارغوانی با گلدوزی‌های برنزی بر تن دارد.","locationTag":"تالار انجمن آوند","sessionTag":"جلسه ۲","ac":"۱۲","hp":{"current":40,"max":40},"speed":"۹ متر","abilities":{"str":17,"dex":10,"con":14,"int":18,"wis":16,"cha":14},"savingThrows":"هوش +۷، خرد +۶","resistances":"ندارد","vulnerabilities":"ندارد","immunities":"ندارد","attacks":[],"specialAbilities":[],"tacticsTips":"کلید معماری و راهنمای شناسایی سازه‌های معبد برای سامان.","lootDrops":"ابزارهای معماری باستانی دیوان","dialogueLines":["خون معماران در رگ‌های تو جاری است، فرزندم... سنگ‌ها به یاد دارند."],"isRevealed":true,"updatedAt":"2026-10-27T08:54:45.062Z"}', 0;
INSERT INTO npcs (id, scope_type, scope_id, source_id, source_mode, created_by, name, type, is_revealed, location_tag, session_tag, data, updated_at) VALUES ('npc-kateb-azam-kondavar', 'pack', 'npc-kateb-azam-kondavar', NULL, 'copy', NULL, 'کاتب اعظم کنداور', 'ally', 1, 'کتابخانه کنداور', 'جلسه ۲', '{"id":"npc-kateb-azam-kondavar","name":"کاتب اعظم کنداور","type":"ally","portraitUrl":"https://images.unsplash.com/photo-1534447677768-be436bb09401?auto=format&fit=crop&w=400&q=80","description":"کاتب سالخورده از نژاد مینیاتوری کنداور (حدود ۳۰ سانتی‌متر)؛ گنجینه‌ای از وقایع تاریخی و اسناد کهن.","locationTag":"کتابخانه کنداور","sessionTag":"جلسه ۲","ac":"۱۲","hp":{"current":6,"max":6},"speed":"۶ متر","abilities":{"str":4,"dex":16,"con":10,"int":19,"wis":16,"cha":12},"savingThrows":"هوش +۷","resistances":"ندارد","vulnerabilities":"ندارد","immunities":"ندارد","attacks":[],"specialAbilities":[],"tacticsTips":"پاسخگوی پرسش‌های تاریخی درباره پیمان نخست.","lootDrops":"ذره‌بین بلورین کوچک","dialogueLines":["آرام‌تر ورق بزنید! هر برگی از این کتب، قرنی از رنج است."],"isRevealed":true,"updatedAt":"2026-10-27T08:54:45.062Z"}', 0;
INSERT INTO npcs (id, scope_type, scope_id, source_id, source_mode, created_by, name, type, is_revealed, location_tag, session_tag, data, updated_at) VALUES ('npc-farid-kateb', 'pack', 'npc-farid-kateb', NULL, 'copy', NULL, 'فرید کاتب', 'quest-giver', 1, 'آرشیو اسناد زیرزمینی', 'جلسه ۲', '{"id":"npc-farid-kateb","name":"فرید کاتب","type":"quest-giver","portraitUrl":"https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=400&q=80","description":"کاتب ۳۵ سانتی‌متری کنداور؛ بسیار دقیق و وسواسی که مدام از پریان غرولند می‌کند؛ دارنده نقشه‌های تکمیلی بزرگراه‌های زیرزمینی.","locationTag":"آرشیو اسناد زیرزمینی","sessionTag":"جلسه ۲","ac":"۱۲","hp":{"current":8,"max":8},"speed":"۶ متر","abilities":{"str":5,"dex":15,"con":11,"int":17,"wis":14,"cha":10},"savingThrows":"هوش +۶","resistances":"ندارد","vulnerabilities":"ندارد","immunities":"ندارد","attacks":[],"specialAbilities":[],"tacticsTips":"در ازای مأموریتی برای پیدا کردن جوهر مخصوص، نقشه را ارائه می‌کند.","lootDrops":"بخش دوم نقشه بزرگراه زیرزمینی","dialogueLines":["پریان! همه‌جا را به هم می‌ریزند و اسمش را شعر و ترانه می‌گذارند!","نقشه را می‌خواهید؟ ابتدا مرکب سنگی من را بازگردانید."],"isRevealed":true,"updatedAt":"2026-10-27T08:54:45.062Z"}', 0;
INSERT INTO npcs (id, scope_type, scope_id, source_id, source_mode, created_by, name, type, is_revealed, location_tag, session_tag, data, updated_at) VALUES ('npc-nariman', 'pack', 'npc-nariman', NULL, 'copy', NULL, 'نریمان', 'neutral', 1, 'کوچه‌های تاریک شن‌شین', 'جلسه ۱ و ۲', '{"id":"npc-nariman","name":"نریمان","type":"neutral","portraitUrl":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=400&q=80","description":"همکار پیشین و مخبر شیده در میان سایه‌خواران محله پایین شن‌شین؛ ارتباطات مخفی دارد.","locationTag":"کوچه‌های تاریک شن‌شین","sessionTag":"جلسه ۱ و ۲","ac":"۱۳","hp":{"current":16,"max":16},"speed":"۹ متر","abilities":{"str":11,"dex":15,"con":12,"int":13,"wis":14,"cha":12},"savingThrows":"چابکی +۴","resistances":"ندارد","vulnerabilities":"ندارد","immunities":"ندارد","attacks":[],"specialAbilities":[],"tacticsTips":"منبع اطلاعات محرمانه در برابر دریافت سکه یا اطلاعات متقابل.","lootDrops":"رمزهای مکاتباتی شن‌شین","dialogueLines":["شیده... هنوز زنده‌ای؟ فکر می‌کردم سایه‌ها تو را بلعیده‌اند."],"isRevealed":true,"updatedAt":"2026-10-27T08:54:45.062Z"}', 0;
INSERT INTO npcs (id, scope_type, scope_id, source_id, source_mode, created_by, name, type, is_revealed, location_tag, session_tag, data, updated_at) VALUES ('npc-farakhdad', 'pack', 'npc-farakhdad', NULL, 'copy', NULL, 'فرخداد', 'quest-giver', 1, 'گوشه دورافتاده شن‌شین', 'جلسه ۲', '{"id":"npc-farakhdad","name":"فرخداد","type":"quest-giver","portraitUrl":"https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=400&q=80","description":"آخرین کاتب آریامن در گوشه‌ای دورافتاده از شن‌شین؛ هرگز دانش خود را به رایگان در اختیار کسی قرار نمی‌دهد.","locationTag":"گوشه دورافتاده شن‌شین","sessionTag":"جلسه ۲","ac":"۱۱","hp":{"current":14,"max":14},"speed":"۹ متر","abilities":{"str":8,"dex":12,"con":11,"int":18,"wis":16,"cha":11},"savingThrows":"هوش +۶","resistances":"ندارد","vulnerabilities":"ندارد","immunities":"ندارد","attacks":[],"specialAbilities":[],"tacticsTips":"به دانشی در مورد نمادهای مهر آریامن مسلط است.","lootDrops":"طومار تفسیر کتیبه‌های آریامن","dialogueLines":["دانش بدون بها، بی‌حرمتی به تاریخ است. چه چیزی برای مبادله آورده‌اید؟"],"isRevealed":true,"updatedAt":"2026-10-27T08:54:45.062Z"}', 0;
INSERT INTO locations (id, scope_type, scope_id, source_id, source_mode, created_by, name, region, description, image_url, dm_notes, revealed, parent_id, created_at, updated_at) VALUES ('loc-caravanserai', 'pack', 'loc-caravanserai', NULL, 'copy', NULL, 'کاروانسرای ماه سرخ', 'کویر خاموش', 'کاروانسرایی باستانی با دیوارهای خشتی مستحکم در آستانه کویر خاموش که استراحتگاه کاوشگران فره و کاروان‌های ادویه است.', NULL, 'پناهگاهی امن برای گروه در شروع ماجراجویی؛ در زیرزمین آن یک انبار متروکه با اسناد تاریخی نوژان مخفی شده است.', 1, NULL, 1700000000000, 1700000000000;
INSERT INTO locations (id, scope_type, scope_id, source_id, source_mode, created_by, name, region, description, image_url, dm_notes, revealed, parent_id, created_at, updated_at) VALUES ('loc-crystal-grove', 'pack', 'loc-crystal-grove', NULL, 'copy', NULL, 'بیشه بلورین ورنا', 'ورنا', 'جنگلی مه‌آلود و کهن که در میان درختان درهم‌تنیده آن، بلورهای زمان و جریان‌های ماورایی با نوری بنفش‌فام می‌درخشند.', NULL, 'محل زندگی موجودات زمان‌گریز و پریان کهن؛ هر دور مبارزه ممکن است طنین زمان رخ دهد.', 1, NULL, 1700000000000, 1700000000000;
INSERT INTO locations (id, scope_type, scope_id, source_id, source_mode, created_by, name, region, description, image_url, dm_notes, revealed, parent_id, created_at, updated_at) VALUES ('loc-silent-tower', 'pack', 'loc-silent-tower', NULL, 'copy', NULL, 'برج خاموشی سپیدارون', 'سپیدارون', 'برجی بلند و سنگی بر فراز صخره‌های سپیدارون که موبدان در آن آتش مقدس و کتیبه‌های پیمان را پاسداری می‌کردند.', NULL, 'نگهبان زمان‌گسسته در طبقه فوقانی این برج مستقر است.', 1, NULL, 1700000000000, 1700000000000;
INSERT INTO locations (id, scope_type, scope_id, source_id, source_mode, created_by, name, region, description, image_url, dm_notes, revealed, parent_id, created_at, updated_at) VALUES ('loc-sangkhab-vault', 'pack', 'loc-sangkhab-vault', NULL, 'copy', NULL, 'دخمه سنگ‌خواب شان‌شین', 'شانشین', 'دخمه‌ای مرموز زیر شهر شان‌شین که رازهای مهر دوم و سنگ‌های تثبیت زمان در آن مدفون است.', NULL, 'تنها با باز کردن قفل سنگی ویژه قابل دسترس است؛ پیمانداران مراقب ورودی آن هستند.', 0, NULL, 1700000000000, 1700000000000;
INSERT INTO locations (id, scope_type, scope_id, source_id, source_mode, created_by, name, region, description, image_url, dm_notes, revealed, parent_id, created_at, updated_at) VALUES ('loc-seven-pacts', 'pack', 'loc-seven-pacts', NULL, 'copy', NULL, 'پل هفت‌پیمان', 'مشترک', 'پل سنگی بزرگ و عظیمی که بر فراز دره شکاف واقعیت امتداد یافته و مرز بین سرزمین‌های باستانی زروانیا را پیوند می‌دهد.', NULL, 'محل برخورد نگهبانان و راهزنان شن‌باد.', 1, NULL, 1700000000000, 1700000000000;
INSERT INTO factions (id, scope_type, scope_id, source_id, source_mode, created_by, name, description, attitude, region, revealed, dm_notes, tags, created_at, updated_at) VALUES ('fac-azarin', 'campaign', 'zorvania-c1', NULL, 'copy', NULL, 'موبدان آذرین', 'پاسداران شعله ابدی و راویان اسناد کهن کویر خاموش.', 'متحد', 'کویر خاموش', 1, 'موبدان نقشه برج نگهبانی را در کتیبه‌های زیر آتشکده حفظ کرده‌اند.', '["مذهب","آتش","اسناد"]', 1790499285062, 1793091185062;
INSERT INTO factions (id, scope_type, scope_id, source_id, source_mode, created_by, name, description, attitude, region, revealed, dm_notes, tags, created_at, updated_at) VALUES ('fac-kandavaran', 'campaign', 'zorvania-c1', NULL, 'copy', NULL, 'انجمن کنداوران', 'صنعتگران و معدن‌کاوان کوهپایه‌های سپیدارون که با بقایای ماشین‌های باستانی دیوان کار می‌کنند.', 'بی‌طرف', 'سپیدارون', 1, 'کنداوران به دنبال کلید مخفی دخمه هستند.', '["صنعت","دیوان","آهنگری"]', 1790499285062, 1793091185062;
INSERT INTO factions (id, scope_type, scope_id, source_id, source_mode, created_by, name, description, attitude, region, revealed, dm_notes, tags, created_at, updated_at) VALUES ('fac-fairies', 'campaign', 'zorvania-c1', NULL, 'copy', NULL, 'یاران پریان', 'حافظان بیشه‌های بلورین ورنا و مرزهای مه‌آلود که نسبت به ورود غریبه‌ها محتاطند.', 'مبهم', 'ورنا', 0, 'پریان کلید نفوذ به ساعت نخستین را در اختیار دارند.', '["طبیعت","مهستان","جادو"]', 1790499285062, 1793091185062;
