INSERT INTO notes (id, character_id, owner_id, campaign_id, title, shared_with_dm, data, updated_at) VALUES ('note-sam-1', 'char-saman', 'user-saman', NULL, 'تکه مهر آریامن و صدای دیواره‌ها', 1, '{"id":"note-sam-1","characterId":"char-saman","ownerId":"user-saman","title":"تکه مهر آریامن و صدای دیواره‌ها","body":"وقتی دستم را روی سنگ ورودی سالن گذاشتم، فرکانس عجیبی از ارتعاش مهر به استخوان‌های مچ دستم زد. به نظر می‌رسد این تکه با قفل دروازه اول هم‌نوا است.","sessionTag":"جلسه ۱","category":"clues","pinned":true,"sharedWithDm":true,"updatedAt":"2026-10-27T08:54:45.062Z"}', 0;
INSERT INTO notes (id, character_id, owner_id, campaign_id, title, shared_with_dm, data, updated_at) VALUES ('note-par-1', 'char-pardis', 'user-pardis', NULL, 'تثبیت زمان با نشان فره', 1, '{"id":"note-par-1","characterId":"char-pardis","ownerId":"user-pardis","title":"تثبیت زمان با نشان فره","body":"در جریان مواجهه با گرگ گسستهزمان، نشان فره وقتی درخشید توانست زره و حرکات لرزان موجود را از ۱۶ به ۱۰ سست کند. باید در نبردهای زمانی حواسم به فراخوان فره باشد.","sessionTag":"جلسه ۲","category":"journal","pinned":true,"sharedWithDm":true,"updatedAt":"2026-10-27T08:54:45.062Z"}', 0;
